/**
 * `FORCE_BFF_DOMAIN` is a boolean on `_manifest.json`.
 * `true` → every MFE `env.VITE_API_URL` = `@linm/root-config`.env.VITE_API_URL.
 *
 * Inline twin: `src/index.ejs` `applyLinmRuntimeEnv` — keep flag parse in sync.
 */

export type LinmManifestEnv = {
  VITE_API_URL?: string;
  FORCE_BFF_DOMAIN?: boolean | string;
};

export type LinmMfManifest = {
  env?: LinmManifestEnv;
  timestamp?: string;
  microfrontends?: Record<
    string,
    {
      env?: LinmManifestEnv;
      url?: string;
      routes?: string[];
      default?: boolean;
    }
  >;
};

export function isForceBffFlagOn(value: unknown): boolean {
  return value === true || value === 'true' || value === 1 || value === '1';
}

export function isForceBffDomainEnabled(manifest?: LinmMfManifest | null): boolean {
  if (!manifest) return false;
  const rootEnv = manifest.microfrontends?.['@linm/root-config']?.env;
  return isForceBffFlagOn(manifest.env?.FORCE_BFF_DOMAIN) || isForceBffFlagOn(rootEnv?.FORCE_BFF_DOMAIN);
}

export function readRootViteApiUrl(manifest?: LinmMfManifest | null): string {
  if (!manifest) return '';
  const root = manifest.microfrontends?.['@linm/root-config']?.env?.VITE_API_URL;
  const site = manifest.env?.VITE_API_URL;
  return String(root || site || '').trim().replace(/\/$/, '');
}

const BFF_API_SUFFIX = '/web-bff/api/v1';

/**
 * MFE bundles often bake `VITE_API_URL` into their own `apiClient`.
 * Rewrite `…/web-bff/api/v1/…` to Root `__LINM_AUTH_BFF_BASE__` when forced.
 */
export function rewriteForcedBffFetchUrl(requestUrl: string): string {
  if (typeof window === 'undefined' || window.__LINM_FORCE_BFF_DOMAIN__ !== true) {
    return requestUrl;
  }
  const forced = String(window.__LINM_AUTH_BFF_BASE__ || '').trim().replace(/\/$/, '');
  if (!forced) return requestUrl;

  try {
    const parsed = new URL(requestUrl, window.location.origin);
    const path = parsed.pathname || '';
    const idx = path.indexOf(BFF_API_SUFFIX);
    if (idx === -1) return requestUrl;
    const rest = `${path.slice(idx + BFF_API_SUFFIX.length)}${parsed.search}${parsed.hash}`;
    return `${forced}${rest}`;
  } catch {
    return requestUrl;
  }
}

/** Copy Root `VITE_API_URL` onto every MFE entry (in-memory manifest). */
export function applyForceBffDomainToManifest(
  manifest: LinmMfManifest,
  rootApiUrl: string,
): void {
  if (!manifest.env) manifest.env = {};
  manifest.env.FORCE_BFF_DOMAIN = true;

  const entries = manifest.microfrontends || {};
  for (const name of Object.keys(entries)) {
    const entry = entries[name];
    if (!entry.env) entry.env = {};
    entry.env.VITE_API_URL = rootApiUrl;
    entry.env.FORCE_BFF_DOMAIN = true;
  }
}
