import {
  getSecureItem,
  removeSecureItem,
  setSecureItem,
  type SecureStorageConfig,
} from '../storage/secureStorage';

export const LOGOUT_SIGNAL_KEY = 'app-logout-signal';

const CONFIG: SecureStorageConfig = {
  storageKey: LOGOUT_SIGNAL_KEY,
  version: 1,
  hashKey: 'auth.logoutSignal',
};

export function getLogoutSignal(): string | null {
  return getSecureItem<string>(CONFIG, { allowLegacyPlain: true });
}

export function setLogoutSignal(message: string): void {
  setSecureItem(CONFIG, message);
}

export function clearLogoutSignal(): void {
  removeSecureItem(CONFIG);
}
