import { getSecureItem } from '../storage/secureStorage';
import { logWarn } from '../../logger';

/** Must match common-components `permissionsCacheStorage` SSOT. */
const PERMISSIONS_CACHE_KEY = 'linm:user_permissions';

/** Prefixes registered for `@linm/shell-url` in Root mfe config / fragments. */
const SHELL_URL_MFE_ROUTE_PREFIXES = new Set(['shell', 'shell-url']);

const MENU_TYPE_SHELL = 'shell';

interface PermissionsCacheEntry {
  payload?: {
    navItems?: Array<{
      path?: string | null;
      defaultUrl?: string | null;
      menuType?: string | null;
    }>;
  };
}

function readPermissionsCache(): PermissionsCacheEntry | null {
  return getSecureItem<PermissionsCacheEntry>(
    {
      storageKey: PERMISSIONS_CACHE_KEY,
      version: 1,
      hashKey: 'perm.user',
    },
    {
      allowLegacyPlain: true,
      legacyParse: (raw) => {
        try {
          return JSON.parse(raw) as PermissionsCacheEntry;
        } catch {
          return null;
        }
      },
    },
  );
}

/**
 * After permissions ready: warn when menuType=shell Path is outside Root routes
 * that mount `@linm/shell-url` (must be under `/shell/...` or `/shell-url/...`).
 *
 * Without this, click → navigateToUrl(`/reva/pos`) mounts default MFE, never iframe.
 */
export function auditShellUrlMenuRoutes(): void {
  const raw = readPermissionsCache()?.payload?.navItems;
  if (!Array.isArray(raw)) return;

  const bad: string[] = [];
  for (const item of raw) {
    if ((item.menuType ?? 'route') !== MENU_TYPE_SHELL) continue;
    if (!item.path || !item.defaultUrl) {
      bad.push(`${item.path ?? '(empty path)'} — thiếu Path hoặc DefaultUrl`);
      continue;
    }
    const seg = item.path.replace(/^\//, '').split('/').filter(Boolean)[0];
    if (!seg || !SHELL_URL_MFE_ROUTE_PREFIXES.has(seg)) {
      bad.push(
        `${item.path} — prefix "${seg ?? ''}" không đăng ký cho @linm/shell-url (cần /shell/... hoặc /shell-url/...)`,
      );
    }
  }

  if (bad.length === 0) return;

  logWarn(
    `[ShellUrl] Menu type=shell map lỗi / ngoài route MFE (${bad.length}):\n` +
      bad.map((line) => `  · ${line}`).join('\n'),
  );
}
