const RELOAD_KEY = '_mf_deploy_reload_ts';
const RELOAD_WINDOW_MS = 30 * 60 * 1000; // 30 minutes
const MAX_RELOADS_IN_WINDOW = 3;
const HANDLER_FLAG = '__LINM_DEPLOY_CHUNK_RECOVERY__';
const PENDING_FLAG = '__LINM_DEPLOY_RELOAD_PENDING__';

/** Errors typical when static assets 404 or HTML is served during a deploy window. */
export function isDeployRelatedLoadError(error: unknown): boolean {
  const errStr = String(
    error instanceof Error
      ? `${error.name} ${error.message}`
      : error,
  );
  return (
    /ChunkLoadError/i.test(errStr) ||
    /Loading chunk [\w.-]+ failed/i.test(errStr) ||
    /Loading CSS chunk [\w.-]+ failed/i.test(errStr) ||
    /MIME type ['"]?text\/html/i.test(errStr) ||
    (/Refused to execute script/i.test(errStr) && /\.js/i.test(errStr)) ||
    /Unexpected token\s*['"]?</i.test(errStr) ||
    errStr.includes('__SECRET_INTERNALS_DO_NOT_USE_OR_YOU_WILL_BE_FIRED') ||
    errStr.includes('Failed to fetch') ||
    errStr.includes('NetworkError') ||
    errStr.includes('Unexpected token') ||
    /Error loading .*? from /.test(errStr) ||
    (/404/.test(errStr) && /\.js/i.test(errStr))
  );
}

/**
 * Hard reload with time-windowed cap.
 *
 * Tracks reload timestamps in sessionStorage with a sliding window of 30 min.
 * Do NOT clear the counter on every single-spa start — that re-arms an infinite
 * reload loop when entry loads but lazy chunks still return SPA HTML.
 *
 * Window flag dedupes ejs + root-config handlers firing on the same error.
 */
export function scheduleDeployReload(reason: string, delayMs = 3000): boolean {
  const w = window as Window & { [PENDING_FLAG]?: boolean };
  if (w[PENDING_FLAG]) return true;

  const now = Date.now();
  const raw = sessionStorage.getItem(RELOAD_KEY);
  const timestamps: number[] = raw ? JSON.parse(raw) : [];
  const recent = timestamps.filter((t) => now - t < RELOAD_WINDOW_MS);

  if (recent.length >= MAX_RELOADS_IN_WINDOW) {
    console.warn(
      `[DeployRecovery] Reload cap (${MAX_RELOADS_IN_WINDOW} within ${RELOAD_WINDOW_MS / 60000}min) — waiting for window to expire`,
    );
    return false;
  }

  w[PENDING_FLAG] = true;
  recent.push(now);
  sessionStorage.setItem(RELOAD_KEY, JSON.stringify(recent));

  console.warn(
    `[DeployRecovery] ${reason} — reloading in ${delayMs}ms (${recent.length}/${MAX_RELOADS_IN_WINDOW} within 30min window)`,
  );
  setTimeout(() => window.location.reload(), delayMs);
  return true;
}

/**
 * Clear reload timestamps after a healthy period (call from delayed timer only).
 * Never call from SingleSpa.start() — ChunkLoadError fires after start succeeds.
 */
export function resetDeployReloadCounter(): void {
  sessionStorage.removeItem(RELOAD_KEY);
}

/**
 * Global handlers for webpack lazy-chunk failures after System.import(entry) succeeded.
 * SPA not_found_handling returns index.html (text/html) for missing hashed chunks —
 * that surfaces as ChunkLoadError / MIME refusal, not as System.import rejection.
 */
export function installDeployChunkRecovery(): void {
  const w = window as Window & { [HANDLER_FLAG]?: boolean };
  if (w[HANDLER_FLAG]) return;
  w[HANDLER_FLAG] = true;

  const tryReload = (reason: string, error: unknown): boolean => {
    if (!isDeployRelatedLoadError(error)) return false;
    return scheduleDeployReload(reason, 1500);
  };

  window.addEventListener('unhandledrejection', (event) => {
    if (tryReload('unhandledrejection chunk/deploy load', event.reason)) {
      event.preventDefault();
    }
  });

  window.addEventListener(
    'error',
    (event) => {
      const target = event.target;
      if (target instanceof HTMLScriptElement) {
        const src = target.src || '';
        if (/\.js(\?|$)/i.test(src) && tryReload(`script error: ${src}`, event.error ?? src)) {
          return;
        }
      }
      if (event.error && tryReload('window error chunk/deploy load', event.error)) {
        return;
      }
      // MIME / refused-to-execute often has null error — use message text.
      if (event.message && tryReload('window error message', event.message)) {
        return;
      }
    },
    true,
  );

  // After 2 minutes without another reload schedule, clear the cap so a later
  // deploy still gets recovery attempts in the same tab session.
  window.setTimeout(() => {
    const raw = sessionStorage.getItem(RELOAD_KEY);
    if (!raw) return;
    const timestamps: number[] = JSON.parse(raw);
    const last = timestamps[timestamps.length - 1] ?? 0;
    if (Date.now() - last > 2 * 60 * 1000) {
      resetDeployReloadCounter();
    }
  }, 2 * 60 * 1000);
}
