import { logError } from '../../logger';

const ERROR_TITLE = 'Không tải được nội dung';
const ERROR_BODY =
  'Các phần khác của hệ thống vẫn hoạt động bình thường. Bạn có thể thử lại hoặc tiếp tục sử dụng các chức năng khác.';

export function resolveMfeDom(props: { domElement?: HTMLElement } | null | undefined): HTMLElement | undefined {
  return props?.domElement ?? document.getElementById('main-content') ?? undefined;
}

export function renderMfeError(el: HTMLElement | undefined, appName: string): void {
  if (!el) return;
  const safeName = String(appName || '').replace(/[<>&"]/g, '');
  el.innerHTML = `
    <div class="linm-mfe-error" role="alert" data-mfe="${safeName}">
      <div class="linm-mfe-error__icon" aria-hidden="true">!</div>
      <h2 class="linm-mfe-error__title">${ERROR_TITLE}</h2>
      <p class="linm-mfe-error__body">${ERROR_BODY}</p>
      <button type="button" class="linm-mfe-error__retry" data-linm-mfe-retry>Thử lại</button>
    </div>
  `;
  el.querySelector('[data-linm-mfe-retry]')?.addEventListener('click', () => {
    window.location.reload();
  });
}

function invokeLifecycle(fn: unknown, props: unknown): Promise<unknown> {
  const fns = Array.isArray(fn) ? fn : [fn];
  return fns.reduce<Promise<unknown>>(
    (chain, item) =>
      chain.then(() => {
        if (typeof item !== 'function') return undefined;
        try {
          const result = item(props);
          return result != null && typeof result.then === 'function'
            ? result
            : Promise.resolve(result);
        } catch (err) {
          return Promise.reject(err);
        }
      }),
    Promise.resolve(),
  );
}

export type MfeLifecycles = {
  name: string;
  bootstrap: (props: unknown) => Promise<unknown>;
  mount: (props: unknown) => Promise<unknown>;
  unmount: (props: unknown) => Promise<unknown>;
};

export function createMfeErrorLifecycle(appName: string): MfeLifecycles {
  return {
    name: appName,
    bootstrap: () => Promise.resolve(),
    mount: (props: unknown) => {
      renderMfeError(resolveMfeDom(props as { domElement?: HTMLElement }), appName);
      return Promise.resolve();
    },
    unmount: (props: unknown) => {
      const el = resolveMfeDom(props as { domElement?: HTMLElement });
      if (el) el.innerHTML = '';
      return Promise.resolve();
    },
  };
}

/** Wrap MFE/parcel lifecycles: always return a Promise; on fail show error UI and resolve so the shell stays up. */
export function wrapMfeLifecycles(appName: string, module: unknown): MfeLifecycles {
  const raw = module as Record<string, unknown> | null;
  const src =
    raw?.default &&
    typeof (raw.default as Record<string, unknown>).bootstrap === 'function'
      ? (raw.default as Record<string, unknown>)
      : raw;

  if (!src || typeof src.mount !== 'function') {
    logError(`[SingleSpa] ${appName} has no mount lifecycle — showing MFE error`);
    return createMfeErrorLifecycle(appName);
  }

  return {
    name: appName,
    bootstrap: (props) =>
      invokeLifecycle(src.bootstrap, props).catch((err) => {
        logError(`[SingleSpa] ${appName} bootstrap failed: ${err}`);
        return undefined;
      }),
    mount: (props) =>
      invokeLifecycle(src.mount, props).catch((err) => {
        logError(`[SingleSpa] ${appName} mount failed: ${err}`);
        renderMfeError(resolveMfeDom(props as { domElement?: HTMLElement }), appName);
        return undefined;
      }),
    unmount: (props) =>
      invokeLifecycle(src.unmount, props).catch((err) => {
        logError(`[SingleSpa] ${appName} unmount failed: ${err}`);
        const el = resolveMfeDom(props as { domElement?: HTMLElement });
        if (el) el.innerHTML = '';
        return undefined;
      }),
  };
}
