/**
 * Cross-tab token synchronisation via BroadcastChannel.
 *
 * SSOT: @linm-soft-org/linm-web-common-components/src/utils/crossTabTokenSync.ts
 * Root bundles this copy — keep in sync on common-components publish.
 */

import { getAuthToken, getAuthRefreshToken, setAuthTokens } from '../storage/authTokenStorage';

const TOKEN_REFRESH_CHANNEL = 'app-token-refresh-channel';

let _crossTabTokenVersion = 0;

export function getCrossTabTokenVersion(): number {
  return _crossTabTokenVersion;
}

export function broadcastTokenRefresh(accessToken: string, refreshToken: string): void {
  try {
    const channel = new BroadcastChannel(TOKEN_REFRESH_CHANNEL);
    channel.postMessage({
      type: 'TOKEN_REFRESH',
      accessToken,
      refreshToken,
      ts: Date.now(),
    });
    channel.close();
  } catch {
    // BroadcastChannel unsupported
  }
}

export function initializeCrossTabTokenSync(): void {
  try {
    const channel = new BroadcastChannel(TOKEN_REFRESH_CHANNEL);
    channel.onmessage = (event: MessageEvent) => {
      if (event.data?.type !== 'TOKEN_REFRESH') return;

      const { accessToken, refreshToken } = event.data;
      if (typeof accessToken !== 'string' || typeof refreshToken !== 'string') return;

      const curAccess = getAuthToken();
      const curRefresh = getAuthRefreshToken();
      if (curAccess === accessToken && curRefresh === refreshToken) return;

      setAuthTokens({ accessToken, refreshToken });
      _crossTabTokenVersion++;
    };
  } catch {
    // BroadcastChannel unavailable
  }
}
