import { hasValidAuthToken } from '../storage/authTokenStorage';
import { auditShellUrlMenuRoutes } from './shellUrlMenuAudit';

const PERMISSION_LOADING = 'linm:permission:loading';
const PERMISSION_READY = 'linm:permission:ready';
/** Fail-safe — unblock if @linm/nav never signals ready (nav error, API 503 hang). */
const BOOTSTRAP_MAX_MS = 25_000;
const DEFAULT_LOADING_LABEL = 'Đang tải hệ thống…';
/** Public loading mark — only when Root allowChangeLinmLoading. Allow OFF rejects /icons. */
const DEFAULT_LOGO_SIZE = 64;

type LogoLoadingConfig = {
  logoSrc?: string;
  label?: string;
  logoSize?: number;
};

type ShellBrandingSnap = {
  icon?: string;
  loadingLabel?: string;
  allowChangeLinmLoading?: boolean;
  loadingIcon?: string;
  sidebarLogoSize?: number;
};

declare global {
  interface Window {
    __LINM_LOADING__?: LogoLoadingConfig;
    __LINM_SHELL_BRANDING__?: ShellBrandingSnap;
  }
}

function trim(value?: string): string {
  return (value ?? '').trim();
}

function escapeAttr(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function pickLogoSize(value?: number): number | undefined {
  if (typeof value !== 'number' || !Number.isFinite(value)) return undefined;
  if (value < 16 || value > 256) return undefined;
  return Math.round(value);
}

/**
 * Same Root gate as common `resolveLogoLoadingConfig`.
 * Allow OFF → no public `/icons` (common linmBrand after MFE load).
 * Allow ON → `__LINM_LOADING__` → loadingIcon (never nav `branding.icon`).
 */
function resolveBootstrapLoadingConfig(): Required<LogoLoadingConfig> {
  const loading = window.__LINM_LOADING__;
  const branding = window.__LINM_SHELL_BRANDING__;
  const allowChange = branding?.allowChangeLinmLoading === true;
  const loadingIcon = allowChange ? trim(branding?.loadingIcon) : '';
  const logoSrc = allowChange
    ? trim(loading?.logoSrc) || loadingIcon || ''
    : '';
  const label =
    trim(loading?.label) || trim(branding?.loadingLabel) || DEFAULT_LOADING_LABEL;
  const logoSize =
    pickLogoSize(loading?.logoSize) ?? DEFAULT_LOGO_SIZE;
  return { logoSrc, label, logoSize };
}

const PUBLIC_PATHS = [
  '/login',
  '/logout',
  '/session-expired',
  '/oidc-callback',
  '/oidc-silent-renew',
  '/unauthorized',
  '/scyk/bao-su-co',
  '/integration/users/register',
];

/** Shell-embed routes (ShellUrl standalone FAB) — no nav/permissions needed. */
const SHELL_EMBED_PREFIXES = ['/shell-url', '/shell'];

function normalizePath(pathname: string): string {
  if (!pathname || pathname === '/') return pathname || '/';
  return pathname.endsWith('/') ? pathname.slice(0, -1) : pathname;
}

function isPublicPath(pathname: string): boolean {
  const normalized = normalizePath(pathname);
  return PUBLIC_PATHS.some(
    (p) => normalized === p || normalized.startsWith(`${p}/`),
  );
}

function isShellEmbedPath(pathname: string): boolean {
  const n = normalizePath(pathname);
  return SHELL_EMBED_PREFIXES.some(
    (p) => n === p || n.startsWith(`${p}/`),
  );
}

function isMobilePhonePath(pathname: string): boolean {
  const n = normalizePath(pathname);
  return n === '/m' || n.startsWith('/m/');
}

function shouldGatePermissions(pathname: string): boolean {
  return (
    hasValidAuthToken() &&
    !isPublicPath(pathname) &&
    !isShellEmbedPath(pathname) &&
    !isMobilePhonePath(pathname)
  );
}

/**
 * Full-page spinner only on cold permission bootstrap (first menu load).
 * After menu ready, route refresh uses @linm/nav main-content skeleton only.
 */
export function setupPermissionsBootstrap(): void {
  let overlay = document.getElementById('linm-perm-bootstrap');
  if (!overlay) {
    const { logoSrc, label, logoSize } = resolveBootstrapLoadingConfig();
    overlay = document.createElement('div');
    overlay.id = 'linm-perm-bootstrap';
    overlay.setAttribute('role', 'status');
    overlay.setAttribute('aria-live', 'polite');
    overlay.setAttribute('aria-busy', 'true');
    overlay.style.setProperty('--linm-loading-logo-size', `${logoSize}px`);
    const logoHtml = logoSrc
      ? `<img class="linm-perm-bootstrap__logo" src="${escapeAttr(logoSrc)}" alt="" width="${logoSize}" height="${logoSize}" />`
      : '';
    overlay.innerHTML = `
      <div class="linm-perm-bootstrap__stage" aria-hidden="true">${logoHtml}</div>
      <p class="linm-perm-bootstrap__label">${escapeAttr(label)}</p>
    `;
    document.body.appendChild(overlay);
  }

  let busy = false;
  let ready = false;
  /** After first PERMISSION_READY, route refresh uses main-area skeleton only. */
  let menuEverReady = false;
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  const clearBootstrapTimeout = () => {
    if (timeoutId != null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  const sync = () => {
    const gate = shouldGatePermissions(window.location.pathname);
    const show = gate && (busy || !ready);
    overlay!.classList.toggle('visible', show);
    overlay!.setAttribute('aria-busy', show ? 'true' : 'false');
    if (!show) clearBootstrapTimeout();
  };

  const unblock = () => {
    busy = false;
    ready = true;
    clearBootstrapTimeout();
    sync();
  };

  const armBootstrapTimeout = () => {
    clearBootstrapTimeout();
    if (!shouldGatePermissions(window.location.pathname)) return;
    timeoutId = setTimeout(unblock, BOOTSTRAP_MAX_MS);
  };

  const onLoading = () => {
    if (menuEverReady) return;
    busy = true;
    ready = false;
    armBootstrapTimeout();
    sync();
  };

  const onReady = () => {
    menuEverReady = true;
    unblock();
    try {
      auditShellUrlMenuRoutes();
    } catch {
      /* non-critical audit */
    }
  };

  const onAuthChange = () => {
    if (!hasValidAuthToken()) {
      menuEverReady = false;
    }
    busy = false;
    ready = menuEverReady;
    if (shouldGatePermissions(window.location.pathname) && !menuEverReady) {
      busy = true;
      ready = false;
      armBootstrapTimeout();
    } else {
      clearBootstrapTimeout();
    }
    sync();
  };

  window.addEventListener(PERMISSION_LOADING, onLoading);
  window.addEventListener(PERMISSION_READY, onReady);
  window.addEventListener('linm:auth:token-changed', onAuthChange);
  window.addEventListener('linm:auth:changed', onAuthChange);
  window.addEventListener('linm:company:changed', onAuthChange);
  window.addEventListener('single-spa:routing-event', () => {
    if (shouldGatePermissions(window.location.pathname) && (busy || !ready)) {
      armBootstrapTimeout();
    }
    sync();
  });

  if (shouldGatePermissions(window.location.pathname)) {
    busy = true;
    ready = false;
    armBootstrapTimeout();
  }
  sync();
}
