import {
  getSecureItem,
  removeSecureItem,
  setSecureItem,
  type SecureStorageConfig,
} from './secureStorage';

export const PENDING_COMPANY_KEY = 'pending_company_code';

const CONFIG: SecureStorageConfig = {
  storageKey: PENDING_COMPANY_KEY,
  version: 1,
  hashKey: 'auth.pendingCompany',
};

export function getPendingCompanyCode(): string | null {
  const raw = getSecureItem<string>(CONFIG, { allowLegacyPlain: true });
  return raw?.trim() || null;
}

export function setPendingCompanyCode(code: string): void {
  setSecureItem(CONFIG, code.trim().toUpperCase());
}

export function clearPendingCompanyCode(): void {
  removeSecureItem(CONFIG);
}
